const field=document.getElementById('starfield');const count=Math.min(180,Math.floor(innerWidth*innerHeight/9000));for(let i=0;i<count;i++){const s=document.createElement('span');s.className='star';s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.setProperty('--o',(Math.random()*.65+.2).toFixed(2));s.style.setProperty('--d',(Math.random()*8+5).toFixed(1)+'s');s.style.setProperty('--x',(Math.random()*50-25).toFixed(0)+'px');s.style.setProperty('--y',(Math.random()*50-25).toFixed(0)+'px');s.style.transform=`scale(${(Math.random()*.8+.4).toFixed(2)})`;field.appendChild(s)}
let tx=0,ty=0,cx=0,cy=0;addEventListener('mousemove',e=>{tx=(e.clientX/innerWidth-.5)*18;ty=(e.clientY/innerHeight-.5)*18});function move(){cx+=(tx-cx)*.045;cy+=(ty-cy)*.045;field.style.transform=`translate3d(${cx}px,${cy}px,0)`;requestAnimationFrame(move)}move();
